<script setup lang="ts">
import {pressTo} from '../../utils/press';
import {computed,nextTick,ref,watch} from 'vue';
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';
import {useUserStore} from '../../store/studio-user';
import {useStudioNative} from '../../utils/studio-native';
import {studioCall} from '../../utils/miniapp-client';
import {adminCall} from '../../utils/studio-admin';
import {adminView} from '../../utils/studio-admin-cache';
import copy from '../../../../05_studio/src/content/customer-notifications.json';
const user=useUserStore(),{language,keyboardOpen,shellStyle,say,changeLanguage}=useStudioNative();
const thread=ref(''),reservation=ref(''),items=ref<any[]>([]),draft=ref(''),error=ref(''),sending=ref(false),hasOlder=ref(false),scrollTo=ref('');
let active=false,alive=true,loading=false,generation=0,timer:ReturnType<typeof setInterval>|undefined,key='',sentBody='',view:ReturnType<typeof adminView<any>>;
const endpoint=computed(()=>thread.value?'/manage/site-messages/'+thread.value:'/auth/messages');
const mine=(item:any)=>item.sender_role===(thread.value?'staff':'customer');
const call=<T,>(path:string,data:unknown={},method:'GET'|'POST'='GET')=>thread.value?adminCall<T>(path,data,method):studioCall<T>(path,data,'',user.token,method);
function back(){uni.navigateBack({fail:()=>uni.redirectTo({url:'/pages/auth/studio-account'})});}
function openBooking(id:string){pressTo('/pages/studio/reservation?id='+encodeURIComponent(id));}
function remember(){view?.save({items:items.value,draft:draft.value,hasOlder:hasOlder.value});}
watch(()=>user.token,()=>{generation++;items.value=[];draft.value='';key='';sentBody='';hasOlder.value=false;view=adminView<any>('site-chat:'+thread.value);void load();});
async function load(older=false){if(loading||!active)return;if(!user.token&&!thread.value){uni.navigateTo({url:'/pages/auth/studio-login'});return;}loading=true;const token=user.token,n=generation;
 try{const params=older&&items.value.length?{before:items.value[0].seq}:items.value.length?{after:items.value[items.value.length-1].seq}:{};const result=await call<any>(endpoint.value,params);if(!alive||token!==user.token||n!==generation)return;
 const rows=[...(older?result.items:items.value),...(older?items.value:result.items)];items.value=[...new Map(rows.map(r=>[r.id,r])).values()].sort((a,b)=>a.seq-b.seq);if(older||!('after' in params))hasOlder.value=result.has_older;
 if(result.items.length&&!older){await nextTick();scrollTo.value='site-message-'+items.value[items.value.length-1].id;}
 if(active&&!older&&items.value.length)void call(endpoint.value+'/read',{seq:items.value[items.value.length-1].seq},'POST').catch(()=>{});remember();
 }catch(e){error.value=say((copy as Record<string,string[]>)[(e as any)?.code]||copy.generic_error);}finally{loading=false;}}
async function send(){const content=draft.value.trim();if(!content||sending.value)return;sending.value=true;error.value='';if(sentBody!==content){key='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const n=Math.random()*16|0;return(c==='x'?n:(n&3)|8).toString(16);});sentBody=content;}
 try{await call(endpoint.value,{content,request_id:key,reservation_id:reservation.value},'POST');draft.value='';key='';sentBody='';await load();remember();}catch(e){error.value=say((copy as Record<string,string[]>)[(e as any)?.code]||copy.generic_error);}finally{sending.value=false;}}
onLoad(q=>{thread.value=typeof q?.thread==='string'?q.thread:'';reservation.value=typeof q?.reservation==='string'?q.reservation:'';view=adminView<any>('site-chat:'+thread.value);if(view.snapshot){items.value=view.snapshot.items;draft.value=view.snapshot.draft;hasOlder.value=view.snapshot.hasOlder;}});
// Customer chat is retired; staff thread links still use the authorized manage API.
onShow(()=>{if(!thread.value){uni.redirectTo({url:'/pages/auth/studio-account'});return;}active=true;void load();clearInterval(timer);timer=setInterval(()=>void load(),2000);});onHide(()=>{active=false;clearInterval(timer);remember();});onUnload(()=>{active=false;alive=false;generation++;clearInterval(timer);remember();});
</script>
<template><view class="site-native-shell" :style="shellStyle"><view class="site-native-heading"><button class="admin-icon" @tap="back">‹</button><text>{{say(thread?copy.site_messages:copy.contact_host)}}</text><button class="admin-language" @tap="changeLanguage">{{language==='zh'?'EN':'中文'}}</button></view><text v-if="error" class="admin-error">{{error}}</text><scroll-view scroll-y class="site-native-body" :scroll-into-view="scrollTo" :scroll-with-animation="false"><view class="site-native-messages"><button v-if="hasOlder" class="admin-secondary" @tap="load(true)">{{say(copy.more)}}</button><text v-if="!items.length" class="admin-empty">{{say(copy.empty)}}</text><view v-for="item in items" :key="item.id" :id="'site-message-'+item.id" :class="['site-native-message',{mine:mine(item),system:item.sender_role==='system'}]"><text class="admin-muted">{{say(item.sender_role==='system'?copy.system:mine(item)?copy.you:thread?copy.customer:copy.host)}}</text><text class="site-native-text" selectable>{{item.body}}</text><button v-if="item.reservation_id&&!thread" class="studio-native-link" @tap="openBooking(item.reservation_id)">{{say(copy.view_booking)}}</button></view></view></scroll-view><view class="site-native-composer"><textarea v-model="draft" :placeholder="say(copy.reply)" :adjust-position="false" maxlength="4000"/><button class="admin-primary" :disabled="sending||!draft.trim()" hover-class="admin-pressed" @tap="send">{{say(sending?copy.sending:copy.send)}}</button></view></view></template>
<style scoped>.site-native-shell{height:var(--studio-window-height,100vh);display:flex;flex-direction:column;background:#fff;box-sizing:border-box;padding-bottom:var(--studio-safe-bottom,0px);color:#30434e;font-family:'Studio Outfit',sans-serif}.site-native-heading{display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:1px solid #e0e8ed}.site-native-heading>text{flex:1;font-size:21px}.site-native-body{flex:1;min-height:0;height:0}.site-native-messages{padding:16px;display:flex;flex-direction:column;gap:12px}.site-native-message{align-self:flex-start;max-width:88%;padding:12px;border-radius:12px;background:#f1f6f8;display:flex;flex-direction:column;gap:7px;box-sizing:border-box;overflow-wrap:anywhere}.site-native-message.mine{align-self:flex-end;background:#e4f0f7}.site-native-message.system{align-self:stretch;max-width:none;background:#faf8f1}.site-native-text{white-space:pre-wrap;font-size:14px;line-height:1.7}.site-native-composer{padding:12px;display:flex;gap:10px;align-items:flex-end;border-top:1px solid #dce5ea}.site-native-composer textarea{box-sizing:border-box;flex:1;min-width:0;height:74px;font-size:16px;padding:10px;border:1px solid #dce5ea;border-radius:10px}.site-native-composer button{flex-shrink:0;min-height:44px}@media(max-height:450px){.site-native-composer textarea{height:48px}.site-native-heading{padding:4px 12px}}</style>
